const raw = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const firstName = String(raw.firstName || '').trim();
const lastName = String(raw.lastName || '').trim();
const email = String(raw.email || '').trim();
const phone = String(raw.phone || '').trim();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

if (!email || !emailValid) {
  return [{
    json: {
      valid: false,
      error: 'A valid email is required.',
      firstName,
      lastName,
      email,
      phone,
    },
  }];
}

return [{
  json: {
    valid: true,
    firstName,
    lastName,
    email,
    phone,
    totalScore: Number(raw.totalScore) || 0,
    numbersScore: Number(raw.numbersScore) || 0,
    trustScore: Number(raw.trustScore) || 0,
    knownScore: Number(raw.knownScore) || 0,
    foundScore: Number(raw.foundScore) || 0,
    topPriority: String(raw.topPriority || '').trim(),
    source: String(raw.source || '1m-scorecard').trim() || '1m-scorecard',
    submittedAt: raw.submittedAt || new Date().toISOString(),
  },
}];
